def choose_move(observation):
    def _pair(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def _sgn(a, b):
        return 0 if a == b else (1 if a > b else -1)

    def _clip(d):
        return -1 if d < -1 else (1 if d > 1 else d)

    def _dist(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def _best_target(points, origin, mode="min"):
        best = None
        best_score = None
        for p in points or []:
            if not isinstance(p, (list, tuple)) or len(p) < 2:
                continue
            pt = (p[0], p[1])
            score = _dist(pt, origin)
            if best is None or (mode == "min" and score < best_score) or (mode == "max" and score > best_score):
                best = pt
                best_score = score
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = _pair(observation.get("self_position", (0, 0)))
    ox, oy = _pair(observation.get("opponent_position", (sx, sy)))
    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            tx, ty = ox, oy
            return [_clip(_sgn(sx, tx)), _clip(_sgn(sy, ty))]
        corners = []
        if gw > 0 and gh > 0:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = _best_target(corners, (ox, oy), mode="max")
        if target is None:
            return [0, 0]
        return [_clip(_sgn(sx, target[0])), _clip(_sgn(sy, target[1]))]

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier")
            or observation.get("targets")
            or []
        )
        target = _best_target(targets, (sx, sy), mode="min")
        if target is None:
            # If nothing obvious, bias toward opponent or center.
            if gw > 0 and gh > 0:
                cx, cy = gw // 2, gh // 2
                if observation.get("self_territory"):
                    target = _best_target(observation.get("self_territory"), (ox, oy), mode="max")
                if target is None:
                    target = (cx, cy)
            else:
                target = (ox, oy)
        return [_clip(_sgn(sx, target[0])), _clip(_sgn(sy, target[1]))]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = _best_target(resources, (sx, sy), mode="min")
    if target is not None:
        return [_clip(_sgn(sx, target[0])), _clip(_sgn(sy, target[1]))]

    # Resource denial / fallback: move toward opponent if present, else center-ish.
    if ox != sx or oy != sy:
        return [_clip(_sgn(sx, ox)), _clip(_sgn(sy, oy))]

    if gw > 0 and gh > 0:
        cx, cy = gw // 2, gh // 2
        return [_clip(_sgn(sx, cx)), _clip(_sgn(sy, cy))]

